<?php require "../config.php";$page_title="Login";$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("SELECT * FROM users WHERE email=? LIMIT 1");$s->bind_param("s",$_POST["email"]);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($_POST["password"],$u["password"])){$_SESSION["user_id"]=$u["id"];$_SESSION["user"]=$u;$_SESSION["role"]=$u["role"];$to=$u["role"]==="admin"?"/cgua/admin/":($u["role"]==="lecturer"?"/cgua/lecturer/":"/cgua/student/");header("Location: $to");exit;}$err="Invalid login.";}require "../includes/header.php";?><section class="section portal-shell"><div class="container col-lg-5"><div class="dashboard-card"><?php if($err):?><div class="alert alert-danger"><?=$err?></div><?php endif;?><div class="eyebrow">CGUA Portal</div><h2>Welcome back.</h2><form method="post" class="mt-4"><input class="form-control mb-3" name="email" type="email" placeholder="Email" required><input class="form-control mb-3" name="password" type="password" placeholder="Password" required><button class="btn btn-adventure w-100 rounded-pill">Login</button></form><p class="muted mt-3">Admin: admin@cgua.test / password</p></div></div></section><?php require "../includes/footer.php";?>